package com.example.editor.metamodel.importing.python;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

/** Configura el análisis AST aislado de Python. */
@Component
@ConfigurationProperties(prefix = "dsl.imports.metamodel.python")
public class PythonAstImportProperties {
    private String executable = "python";
    private int timeoutSeconds = 12;
    private int maximumOutputBytes = 4_194_304;
    private boolean fallbackEnabled = true;
    private int maximumConcurrentProcesses = 2;
    private int processAcquireTimeoutSeconds = 5;
    private long outputCollectionTimeoutMillis = 5_000L;
    private long processTerminationGraceMillis = 500L;
    private long processTerminationForceWaitMillis = 1500L;
    private int processTerminationMaximumPasses = 4;
    private long processTreeObservationIntervalMillis = 5L;

    /** Descripción: Obtiene la información correspondiente a «getExecutable» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public String getExecutable() { return executable; }
    /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setExecutable». Entradas: executable: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setExecutable(String executable) { this.executable = executable == null || executable.isBlank() ? "python" : executable; }
    /** Descripción: Obtiene la información correspondiente a «getTimeoutSeconds» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getTimeoutSeconds() { return timeoutSeconds; }
    /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setTimeoutSeconds». Entradas: timeoutSeconds: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setTimeoutSeconds(int timeoutSeconds) { this.timeoutSeconds = Math.max(1, timeoutSeconds); }
    /** Descripción: Obtiene la información correspondiente a «getMaximumOutputBytes» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumOutputBytes() { return maximumOutputBytes; }
    /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setMaximumOutputBytes». Entradas: maximumOutputBytes: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumOutputBytes(int maximumOutputBytes) { this.maximumOutputBytes = Math.max(16_384, maximumOutputBytes); }
    /** Descripción: Evalúa la condición «isFallbackEnabled» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isFallbackEnabled() { return fallbackEnabled; }
    /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setFallbackEnabled». Entradas: fallbackEnabled: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setFallbackEnabled(boolean fallbackEnabled) { this.fallbackEnabled = fallbackEnabled; }
    /** Descripción: Obtiene la información correspondiente a «getMaximumConcurrentProcesses» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumConcurrentProcesses(){return maximumConcurrentProcesses;}
    /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setMaximumConcurrentProcesses». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumConcurrentProcesses(int value){maximumConcurrentProcesses=Math.max(1,value);}
    /** Descripción: Obtiene la información correspondiente a «getProcessAcquireTimeoutSeconds» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getProcessAcquireTimeoutSeconds(){return processAcquireTimeoutSeconds;}
    /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setProcessAcquireTimeoutSeconds». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessAcquireTimeoutSeconds(int value){processAcquireTimeoutSeconds=Math.max(1,value);}
    /** Espera máxima para recoger stdout/stderr una vez terminado el proceso Python. */ /** Descripción: Obtiene la información correspondiente a «getOutputCollectionTimeoutMillis» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getOutputCollectionTimeoutMillis(){return outputCollectionTimeoutMillis;}
    /** Configura una espera acotada para recoger la salida del proceso Python. */ /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setOutputCollectionTimeoutMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setOutputCollectionTimeoutMillis(long value){outputCollectionTimeoutMillis=Math.max(100L,Math.min(30_000L,value));}
    /** Tiempo de gracia para terminar el árbol del analizador Python. */ /** Descripción: Obtiene la información correspondiente a «getProcessTerminationGraceMillis» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getProcessTerminationGraceMillis(){return processTerminationGraceMillis;}
    /** Configura el tiempo de gracia para terminar el árbol del analizador Python. */ /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setProcessTerminationGraceMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessTerminationGraceMillis(long value){processTerminationGraceMillis=Math.max(0L,Math.min(30_000L,value));}
    /** Espera posterior a la terminación forzada del analizador Python. */ /** Descripción: Obtiene la información correspondiente a «getProcessTerminationForceWaitMillis» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getProcessTerminationForceWaitMillis(){return processTerminationForceWaitMillis;}
    /** Configura la espera posterior a la terminación forzada del analizador Python. */ /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setProcessTerminationForceWaitMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessTerminationForceWaitMillis(long value){processTerminationForceWaitMillis=Math.max(0L,Math.min(30_000L,value));}
    /** Intervalo de observación para conservar descendientes Python aunque la raíz termine. */ /** Descripción: Obtiene la información correspondiente a «getProcessTreeObservationIntervalMillis» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getProcessTreeObservationIntervalMillis(){return processTreeObservationIntervalMillis;}
    /** Configura el intervalo de observación del árbol Python. */ /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setProcessTreeObservationIntervalMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessTreeObservationIntervalMillis(long value){processTreeObservationIntervalMillis=Math.max(1L,Math.min(1_000L,value));}
    /** Reescaneos máximos del árbol de procesos Python. */ /** Descripción: Obtiene la información correspondiente a «getProcessTerminationMaximumPasses» dentro de PythonAstImportProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getProcessTerminationMaximumPasses(){return processTerminationMaximumPasses;}
    /** Configura los reescaneos máximos del árbol de procesos Python. */ /** Descripción: Actualiza el estado gestionado por PythonAstImportProperties mediante la operación «setProcessTerminationMaximumPasses». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessTerminationMaximumPasses(int value){processTerminationMaximumPasses=Math.max(1,Math.min(16,value));}
}
